				<div class="aics-wizard-footer"><button type="button" class="button" data-aics-auto-back><?php esc_html_e('Back','ai-content-studio');?></button><button type="submit" class="button button-primary aics-button-primary" data-aics-auto-next><?php esc_html_e('Save and Continue','ai-content-studio');?></button><button type="button" class="button" data-aics-auto-save-inactive><?php esc_html_e('Save Inactive','ai-content-studio');?></button><button type="button" class="button button-primary aics-button-primary" data-aics-auto-activate <?php disabled($activation_blocked);?>><?php esc_html_e('Activate Automation','ai-content-studio');?></button><button type="button" class="button" data-aics-auto-deactivate><?php esc_html_e('Deactivate Automation','ai-content-studio');?></button></div>
