	private static function render_progress(): void { $labels=array('basics'=>'Basics','content'=>'Content','workflow'=>'Workflow','schedule'=>'Schedule','image'=>'Image','seo'=>'SEO','publishing'=>'Publishing','review'=>'Review'); ?><nav class="aics-wizard-progress" aria-label="<?php esc_attr_e('Automation setup progress','ai-content-studio');?>"><ol><?php $i=0;foreach($labels as $step=>$label):++$i;?><li class="<?php echo 1===$i?'is-active':'is-pending';?>"><button type="button" data-aics-auto-nav="<?php echo esc_attr($step);?>" <?php disabled(1!==$i);?> <?php echo 1===$i?'aria-current="step"':'';?>><span class="aics-step-marker"><?php echo esc_html((string)$i);?></span><span class="aics-step-label"><?php echo esc_html($label);?></span></button></li><?php endforeach;?></ol></nav><?php }

	public static function handle_ajax(): void {
		self::require_permission(); check_ajax_referer(self::SAVE_ACTION,self::NONCE_NAME);
		$steps=array('basics','content','workflow','schedule','image','seo','publishing','review');$step=sanitize_key(wp_unslash($_POST['wizard_step']??'basics'));$intent=sanitize_key(wp_unslash($_POST['wizard_intent']??'next'));
		if(!in_array($step,$steps,true)||!in_array($intent,array('next','save_inactive','activate','deactivate'),true)){wp_send_json_error(array('message'=>__('Invalid wizard request.','ai-content-studio')),400);}
		$input=self::request_data();$stored=(new AICS_Automation_Profile_Service())->get_default_profile();
		if('activate'===$intent){$input['enabled']='1';}elseif(in_array($intent,array('save_inactive','deactivate'),true)){$input['enabled']='0';}elseif('active'===($stored['status']??'')){$input['enabled']='1';}
		$result=(new AICS_Automation_Profile_Service())->save($input);if(empty($result['success'])){$errors=is_array($result['errors']??null)?$result['errors']:array();$message=self::first_error_message($errors);wp_send_json_error(array('message'=>$message?:__('Review the configuration values before continuing.','ai-content-studio'),'errors'=>$errors),422);}
		$profile=(new AICS_Automation_Profile_Service())->get_default_profile();ob_start();self::render_review($profile);$review=ob_get_clean();$notice='save_inactive'===$intent?__('Automation saved. It will not run until activated.','ai-content-studio'):('deactivate'===$intent?__('Automation deactivated. It will not run until activated.','ai-content-studio'):__('Automation settings saved.','ai-content-studio'));wp_send_json_success(array('step'=>$step,'profile_id'=>absint($profile['id']??0),'profile_name'=>(string)($profile['profile_name']??''),'next_run'=>self::display_datetime($profile['next_run_at']??null,__('Not scheduled','ai-content-studio')),'status'=>$profile['status']??'disabled','review_html'=>$review,'notice'=>$notice));
	}

	public static function handle_save(): void {
		self::require_permission();
		check_admin_referer( self::SAVE_ACTION, self::NONCE_NAME );
		$input = self::request_data();
		$result = ( new AICS_Automation_Profile_Service() )->save( $input );
		if ( ! $result['success'] ) {
			set_transient( self::state_key(), array( 'data'=>$result['data'], 'errors'=>$result['errors'] ), 5 * MINUTE_IN_SECONDS );
			self::redirect( $result['code'] );
		}
		self::redirect( $result['code'] );
	}

	private static function render_review( array $profile ): void {
		$active='active'===($profile['status']??'');$content=$profile['content_settings']??array();$rules=$profile['workflow_rules']??array();$publishing=$profile['publishing_settings']??array();$image=AICS_Automation_Featured_Image_Settings::normalize_stored($content['featured_images']??array());$seo=AICS_SEO_Configuration::normalize_stored($content['seo']??array(),false);$modes=array('autopilot'=>__('Autopilot','ai-content-studio'),'approval'=>__('Approval Workflow','ai-content-studio'));$publish_labels=array('draft'=>__('Draft','ai-content-studio'),'schedule'=>__('Schedule','ai-content-studio'),'publish'=>__('Publish','ai-content-studio'));$approval_labels=array();if(!empty($rules['require_idea_approval'])){$approval_labels[]=__('Ideas','ai-content-studio');}if(!empty($rules['require_article_approval'])){$approval_labels[]=__('Articles','ai-content-studio');}if(!empty($rules['require_publish_approval'])){$approval_labels[]=__('Publishing','ai-content-studio');}$approvals=$approval_labels?implode(', ',$approval_labels):__('None','ai-content-studio');
		$next_publish=$profile['next_run_at']??null;$preparation_publish=$next_publish;$latest_runs=$active?(new AICS_Automation_Run_Repository())->get_runs(array('profile_id'=>absint($profile['id']??0),'limit'=>1,'orderby'=>'id','order'=>'DESC')):array();if($latest_runs&&in_array($latest_runs[0]['status'],array('queued','running','retrying'),true)){$run_publish=(new AICS_Automation_Run_Repository())->get_publish_at($latest_runs[0]);if(is_string($run_publish)){$preparation_publish=$run_publish;}}$immediate_preparation=$active&&is_string($preparation_publish)&&$preparation_publish<=gmdate('Y-m-d H:i:s',time()+(30*MINUTE_IN_SECONDS));?><header class="aics-review-heading"><h2><?php esc_html_e('Review & Activate','ai-content-studio');?></h2><p><?php esc_html_e('Review the important settings below, then activate your automation.','ai-content-studio');?></p></header><section class="aics-card aics-automation-review-card" aria-labelledby="aics-review-summary-heading"><div class="aics-card-header"><h3 id="aics-review-summary-heading"><?php esc_html_e('Automation Summary','ai-content-studio');?></h3></div><div class="aics-card-body"><div class="aics-review-groups">
		<?php if(!$active&&self::is_short_notice_schedule($profile['schedule_settings']??array())):?><span hidden data-aics-short-notice="1"></span><?php endif;?><div><h4><?php esc_html_e('Automation','ai-content-studio');?></h4><dl><div><dt><?php esc_html_e('Profile name','ai-content-studio');?></dt><dd><?php echo esc_html($profile['profile_name']??__('Untitled automation','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Workflow','ai-content-studio');?></dt><dd><?php echo esc_html($modes[$profile['mode']??'autopilot']??__('Autopilot','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Status','ai-content-studio');?></dt><dd><span class="aics-review-chip"><?php echo esc_html($active?__('Active','ai-content-studio'):__('Inactive','ai-content-studio'));?></span></dd></div></dl></div>
		<div><h4><?php esc_html_e('Content','ai-content-studio');?></h4><dl><div><dt><?php esc_html_e('Ideas per cycle','ai-content-studio');?></dt><dd><?php echo esc_html(number_format_i18n(absint($content['ideas_per_cycle']??0)));?></dd></div><div><dt><?php esc_html_e('Articles/posts per cycle','ai-content-studio');?></dt><dd><?php echo esc_html(number_format_i18n(absint($content['selected_ideas_per_cycle']??0)));?></dd></div></dl></div>
		<div><h4><?php esc_html_e('Schedule','ai-content-studio');?></h4><dl><div><dt><?php esc_html_e('Frequency','ai-content-studio');?></dt><dd><?php echo esc_html(self::schedule_summary($profile['schedule_settings']??array()));?></dd></div><div><dt><?php esc_html_e('Next Publish','ai-content-studio');?></dt><dd><?php echo esc_html(self::display_datetime($immediate_preparation?$preparation_publish:($profile['next_run_at']??null),$active?__('Not scheduled','ai-content-studio'):__('Available after activation','ai-content-studio')));?></dd></div><?php if($immediate_preparation):?><div><dt><?php esc_html_e('Preparation','ai-content-studio');?></dt><dd><?php esc_html_e('Starts immediately','ai-content-studio');?></dd></div><?php endif;?></dl></div>
		<div><h4><?php esc_html_e('Features','ai-content-studio');?></h4><dl><div><dt><?php esc_html_e('Featured Image','ai-content-studio');?></dt><dd><span class="aics-review-chip"><?php echo esc_html($image['enabled']?__('Enabled','ai-content-studio'):__('Disabled','ai-content-studio'));?></span></dd></div><div><dt><?php esc_html_e('SEO','ai-content-studio');?></dt><dd><span class="aics-review-chip"><?php echo esc_html($seo['enabled']?__('Enabled','ai-content-studio'):__('Disabled','ai-content-studio'));?></span></dd></div><div><dt><?php esc_html_e('Publishing','ai-content-studio');?></dt><dd><?php echo esc_html($publish_labels[$publishing['publishing_mode']??'draft']??__('Draft','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Approvals','ai-content-studio');?></dt><dd><?php echo esc_html($approvals);?></dd></div></dl></div>
		</div><?php if($immediate_preparation):?><div class="notice notice-warning inline"><p><?php esc_html_e('Preparation will start immediately. Because this publish time is less than 30 minutes away, publishing may be delayed if content is not ready in time.','ai-content-studio');?></p></div><?php endif;?><?php if($active&&empty($profile['next_run_at'])):?><div class="notice notice-warning inline"><p><?php esc_html_e('This automation is active but has no scheduled future publication. Review its Schedule settings.','ai-content-studio');?></p></div><?php endif;?></div></section><?php
	}

