	private static function is_short_notice_schedule(array $schedule):bool{$next=(new AICS_Schedule_Calculator())->calculate_next_run($schedule);if(empty($next['success'])||!is_string($next['next_run_utc']??null)){return false;}$publish=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$next['next_run_utc'],new DateTimeZone('UTC'));if(false===$publish){return false;}$now=current_datetime();$seconds=$publish->getTimestamp()-$now->getTimestamp();return $seconds>=0&&$seconds<(30*MINUTE_IN_SECONDS);}

