	private static function render_schedule(array $s):void{?>
		<section class="aics-section" aria-labelledby="aics-schedule-heading"><h2 id="aics-schedule-heading"><?php esc_html_e('Publishing Schedule','ai-content-studio');?></h2><p class="description"><?php esc_html_e('Content preparation starts approximately 30 minutes before publishing.','ai-content-studio');?></p><div class="aics-form-grid">
		<?php $frequency_labels=array('daily'=>__('Daily','ai-content-studio'),'weekly'=>__('Weekly','ai-content-studio'),'monthly'=>__('Monthly','ai-content-studio'));$allowed=array_intersect_key($frequency_labels,array_flip(AICS_Plan_Limits::allowed_automation_frequencies()));$fixed_frequency=1===count($allowed);$frequency=$fixed_frequency?array_keys($allowed)[0]:($s['frequency']??array_keys($allowed)[0]);$interval=$fixed_frequency?AICS_Plan_Limits::minimum_automation_interval():max(absint($s['interval']??1),AICS_Plan_Limits::minimum_automation_interval());if($fixed_frequency){self::fixed_field('schedule_settings[frequency]',__('Frequency','ai-content-studio'),array_values($allowed)[0],input_value:$frequency);}else{self::select_field('schedule_settings[frequency]',__('Frequency','ai-content-studio'),$frequency,$allowed);}self::recurrence_field($interval,$frequency,$fixed_frequency);if($fixed_frequency&&apply_filters('aics_show_automation_upgrade_message',true)):?><div class="aics-field aics-field--full aics-plan-note"><p><strong><?php esc_html_e('Free plan:','ai-content-studio');?></strong> <?php esc_html_e('Weekly automation runs every 1 week.','ai-content-studio');?> <?php self::render_upgrade_link();?> <?php esc_html_e('for daily schedules, flexible intervals, and multiple publishing days.','ai-content-studio');?></p></div><?php endif;?>
		<?php $saved_days=is_array($s['days_of_week']??null)?array_values(array_intersect(array_keys(self::weekdays()),array_map('sanitize_key',array_filter($s['days_of_week'],'is_scalar')))):array();if(AICS_Plan_Limits::max_weekly_publishing_days()>1):?><div class="aics-field aics-field--full" data-aics-weekly-days><span class="aics-field-label"><?php esc_html_e('Publishing Days','ai-content-studio');?></span><div class="aics-checkbox-grid"><?php foreach(self::weekdays() as $v=>$l):?><label class="aics-checkbox-option"><input type="checkbox" name="schedule_settings[days_of_week][]" value="<?php echo esc_attr($v);?>" <?php checked(in_array($v,$saved_days,true));?>> <span><?php echo esc_html($l);?></span></label><?php endforeach;?></div><p class="description"><?php esc_html_e('Choose one or more publishing days for Weekly frequency.','ai-content-studio');?></p><p class="description" data-aics-weekly-guidance hidden><?php esc_html_e('All 7 days is a daily schedule. Select Daily frequency instead.','ai-content-studio');?></p></div><?php $day_count=count($saved_days);$posts=max(1,absint($s['posts_per_period']??1));$interval=max(1,absint($s['interval']??1));?><p class="aics-field aics-field--full description" data-aics-weekly-summary><?php echo esc_html(self::weekly_volume_summary($day_count,$posts,$interval));?></p><?php else:$publishing_day=$saved_days[0]??'monday';self::select_field('schedule_settings[days_of_week][]',__('Publishing Day','ai-content-studio'),$publishing_day,self::weekdays(),__('Choose the single publishing day used by Weekly frequency.','ai-content-studio'));endif;?>
		<?php self::select_field('schedule_settings[publish_time]',__('Preferred Publishing Time','ai-content-studio'),$s['publish_time']??'10:00',self::publishing_time_slots()); self::simple_input('date','schedule_settings[start_date]',__('Start Date','ai-content-studio'),$s['start_date']??''); self::simple_input('date','schedule_settings[end_date]',__('End Date','ai-content-studio'),$s['end_date']??'');?>
		</div></section><?php }

