			'invalid_automation_name' => array( 'error', __( 'Enter a valid automation name.', 'ai-content-studio' ) ),
			'selected_ideas_exceed_generated' => array( 'error', __( 'Ideas selected per cycle cannot exceed ideas generated.', 'ai-content-studio' ) ),
			'weekly_days_required' => array( 'error', 1===AICS_Plan_Limits::max_weekly_publishing_days()?__( 'Weekly automation requires exactly one publishing day.', 'ai-content-studio' ):__( 'Weekly automation requires between one and seven publishing days.', 'ai-content-studio' ) ),
			'weekly_all_days_daily' => array( 'error', __( 'All 7 days is a daily schedule. Select Daily frequency instead.', 'ai-content-studio' ) ),
