			'plan_limit_posts_per_period' => array( 'error', self::error_message( 'plan_limit_posts_per_period' ) ),
			'plan_limit_automation_frequency' => array( 'error', self::error_message( 'plan_limit_automation_frequency' ) ),
			'plan_limit_automation_interval' => array( 'error', self::error_message( 'plan_limit_automation_interval' ) ),
				'invalid_monthly_day' => array( 'error', __( 'The monthly publishing day is invalid.', 'ai-content-studio' ) ),
				'invalid_featured_image_settings_source' => array( 'error', __( 'Select a valid featured image settings source.', 'ai-content-studio' ) ),
