	private static function render_errors( array $errors ): void {
		if ( count( $errors ) < 2 ) { return; }
		?><div class="notice notice-error"><p><strong><?php esc_html_e( 'Please correct the following sections:', 'ai-content-studio' ); ?></strong></p><ul><?php foreach ( array_unique( $errors ) as $error ) { ?><li><?php echo esc_html( self::error_message( (string) $error ) ); ?></li><?php } ?></ul></div><?php
	}
	private static function error_message(string $code):string{$label=AICS_Plan_Limits::label();$active=AICS_Plan_Limits::max_active_automation_profiles();$selected=AICS_Plan_Limits::max_selected_ideas_per_cycle();$posts=AICS_Plan_Limits::max_posts_per_period();$active_message=1===$active?sprintf(__('%s supports one active automation.','ai-content-studio'),$label):sprintf(__('%1$s supports %2$d active automations.','ai-content-studio'),$label,$active);$selected_message=1===$selected?sprintf(__('%s supports one selected idea per cycle.','ai-content-studio'),$label):sprintf(__('%1$s supports %2$d selected ideas per cycle.','ai-content-studio'),$label,$selected);$weekly=1===$posts?sprintf(__('%s supports one automated post per week.','ai-content-studio'),$label):sprintf(__('%1$s supports %2$d automated posts per week.','ai-content-studio'),$label,$posts);$messages=array('plan_limit_active_automation_profiles'=>$active_message,'plan_limit_ideas_per_cycle'=>sprintf(__('%1$s supports up to %2$d ideas per cycle.','ai-content-studio'),$label,AICS_Plan_Limits::max_ideas_per_cycle()),'plan_limit_selected_ideas_per_cycle'=>$selected_message,'plan_limit_posts_per_period'=>$weekly,'plan_limit_automation_frequency'=>$weekly,'plan_limit_automation_interval'=>$weekly);return $messages[$code]??str_replace('_',' ',ucfirst($code));}
	private static function first_error_message(array $errors):string{foreach($errors as $error){if(is_scalar($error)&&str_starts_with((string)$error,'plan_limit_')){return self::error_message((string)$error);}}return '';}
	private static function render_upgrade_link():void{?><a class="aics-upgrade-link" href="<?php echo esc_url(AICS_Plan_Limits::upgrade_url());?>"><?php esc_html_e('Upgrade to Pro','ai-content-studio');?></a><?php }
	private static function render_plan_upgrade_notice():void{if(!apply_filters('aics_show_automation_upgrade_message',true)){return;}?><div class="aics-field aics-field--full aics-plan-note"><p><?php echo esc_html(sprintf(__('%s includes 1 automated post per week.','ai-content-studio'),AICS_Plan_Limits::label()));?> <?php self::render_upgrade_link(); ?> <?php esc_html_e('for multiple automations, flexible schedules, and higher publishing volume.','ai-content-studio');?></p></div><?php }
	private static function display_datetime($utc,string $fallback):string{return is_string($utc)&&''!==$utc?get_date_from_gmt($utc,get_option('date_format').' '.get_option('time_format')):$fallback;}
	private static function schedule_summary(array $s):string{$interval=absint($s['interval']??1);$time=is_string($s['publish_time']??null)?$s['publish_time']:'10:00';$parsed=DateTimeImmutable::createFromFormat('!H:i',$time,wp_timezone());$display=$parsed?wp_date(get_option('time_format'),$parsed->getTimestamp(),wp_timezone()):$time;$frequency=$s['frequency']??'weekly';if('daily'===$frequency){return 1===$interval?sprintf(__('Every day at %s.','ai-content-studio'),$display):sprintf(__('Every %1$d days at %2$s.','ai-content-studio'),$interval,$display);}if('weekly'===$frequency){$labels=self::weekdays();$days=array_map(static fn($d)=>$labels[$d]??'',is_array($s['days_of_week']??null)?$s['days_of_week']:array());$day_text=implode(', ',array_filter($days));return 1===$interval?sprintf(__('Every week on %1$s at %2$s.','ai-content-studio'),$day_text,$display):sprintf(__('Every %1$d weeks on %2$s at %3$s.','ai-content-studio'),$interval,$day_text,$display);} $day=absint($s['monthly_day']??1);return 1===$interval?sprintf(__('Every month on day %1$d at %2$s. Shorter months use their last day.','ai-content-studio'),$day,$display):sprintf(__('Every %1$d months on day %2$d at %3$s. Shorter months use their last day.','ai-content-studio'),$interval,$day,$display);}
	private static function weekly_volume_summary(int $days,int $posts,int $interval):string{$total=$days*$posts;$day_text=sprintf(_n('%d publishing day','%d publishing days',$days,'ai-content-studio'),$days);$post_text=sprintf(_n('%d post','%d posts',$posts,'ai-content-studio'),$posts);$total_text=sprintf(_n('%d post','%d posts',$total,'ai-content-studio'),$total);$period=1===$interval?__('per week','ai-content-studio'):sprintf(__('every %d weeks','ai-content-studio'),$interval);return sprintf(__('%1$s × %2$s per occurrence = up to %3$s %4$s','ai-content-studio'),$day_text,$post_text,$total_text,$period);}
	private static function tones():array{return array('professional'=>__('Professional','ai-content-studio'),'friendly'=>__('Friendly','ai-content-studio'),'conversational'=>__('Conversational','ai-content-studio'),'informative'=>__('Informative','ai-content-studio'),'persuasive'=>__('Persuasive','ai-content-studio'));}
	private static function weekdays():array{return array('monday'=>__('Monday','ai-content-studio'),'tuesday'=>__('Tuesday','ai-content-studio'),'wednesday'=>__('Wednesday','ai-content-studio'),'thursday'=>__('Thursday','ai-content-studio'),'friday'=>__('Friday','ai-content-studio'),'saturday'=>__('Saturday','ai-content-studio'),'sunday'=>__('Sunday','ai-content-studio'));}
	private static function publishing_time_slots():array{$slots=array();for($minutes=0;$minutes<1440;$minutes+=5){$hour=intdiv($minutes,60);$minute=$minutes%60;$value=sprintf('%02d:%02d',$hour,$minute);$slots[$value]=sprintf('%d:%02d %s',0===$hour%12?12:$hour%12,$minute,$hour<12?'AM':'PM');}return $slots;}
	private static function join_lines($v):string{return is_array($v)?implode("\n",array_map('strval',$v)):'';}
	private static function text_field(string $name,string $label,$value,int $max,bool $required=false):void{self::simple_input('text',$name,$label,$value,$max,$required);}
	private static function number_field(string $name,string $label,$value,int $min,int $max,string $description=''):void{$step=is_float($value)?'0.1':'1';?><div class="aics-field"><label class="aics-field-label"><?php echo esc_html($label);?><input type="number" name="<?php echo esc_attr($name);?>" value="<?php echo esc_attr((string)$value);?>" min="<?php echo esc_attr((string)$min);?>" max="<?php echo esc_attr((string)$max);?>" step="<?php echo esc_attr($step);?>" required></label><?php if($description){?><p class="description"><?php echo esc_html($description);?></p><?php }?></div><?php }
	private static function fixed_field(string $name,string $label,$display,string $description='',int|string|null $input_value=null):void{$value=null===$input_value?$display:$input_value;?><div class="aics-field aics-plan-fixed-field"><span class="aics-field-label"><?php echo esc_html($label);?></span><strong><?php echo esc_html((string)$display);?></strong><input type="hidden" name="<?php echo esc_attr($name);?>" value="<?php echo esc_attr((string)$value);?>"><?php if($description){?><p class="description"><?php echo esc_html($description);?></p><?php }?></div><?php }
	private static function recurrence_field(int $interval,string $frequency,bool $fixed):void{$unit='daily'===$frequency?_n('day','days',$interval,'ai-content-studio'):_n('week','weeks',$interval,'ai-content-studio');?><div class="aics-field aics-recurrence-field" data-aics-recurrence><span class="aics-field-label"><?php esc_html_e('Repeat every','ai-content-studio');?></span><div class="aics-recurrence-control"><?php if($fixed):?><strong><?php echo esc_html((string)$interval);?></strong><input type="hidden" name="schedule_settings[interval]" value="<?php echo esc_attr((string)$interval);?>"><?php else:?><input type="number" name="schedule_settings[interval]" value="<?php echo esc_attr((string)$interval);?>" min="<?php echo esc_attr((string)AICS_Plan_Limits::minimum_automation_interval());?>" max="31" step="1" required><?php endif;?><span data-aics-recurrence-unit><?php echo esc_html($unit);?></span></div></div><?php }
	private static function simple_input(string $type,string $name,string $label,$value,int $max=0,bool $required=false):void{$id='aics-'.sanitize_html_class(str_replace(array('[',']'),'',$name));?><div class="aics-field"><label id="<?php echo esc_attr($id);?>-label" for="<?php echo esc_attr($id);?>" class="aics-field-label"><?php echo esc_html($label);?></label><input id="<?php echo esc_attr($id);?>" class="widefat" type="<?php echo esc_attr($type);?>" name="<?php echo esc_attr($name);?>" value="<?php echo esc_attr((string)$value);?>" <?php echo 'time'===$type?'step="300"':'';?> <?php echo $max?'maxlength="'.esc_attr((string)$max).'"':'';?> <?php echo $required?'required':'';?>></div><?php }
	private static function textarea_field(string $name,string $label,$value,int $max,string $description=''):void{$id='aics-'.sanitize_html_class(str_replace(array('[',']'),'',$name));?><div class="aics-field aics-field--full"><label for="<?php echo esc_attr($id);?>" class="aics-field-label"><?php echo esc_html($label);?></label><textarea id="<?php echo esc_attr($id);?>" name="<?php echo esc_attr($name);?>" rows="4" maxlength="<?php echo esc_attr((string)$max);?>"><?php echo esc_textarea((string)$value);?></textarea><?php if($description){?><p class="description"><?php echo esc_html($description);?></p><?php }?></div><?php }
	private static function select_field(string $name,string $label,$value,array $options,string $description=''):void{$id='aics-'.sanitize_html_class(str_replace(array('[',']'),'',$name));?><div class="aics-field"><label for="<?php echo esc_attr($id);?>" class="aics-field-label"><?php echo esc_html($label);?></label><select id="<?php echo esc_attr($id);?>" name="<?php echo esc_attr($name);?>"><?php foreach($options as $v=>$l){?><option value="<?php echo esc_attr($v);?>" <?php selected($value,$v);?>><?php echo esc_html($l);?></option><?php }?></select><?php if($description){?><p class="description"><?php echo esc_html($description);?></p><?php }?></div><?php }
	private static function checkbox(string $name,string $label,$checked):void{?><label class="aics-checkbox-option"><input type="checkbox" name="<?php echo esc_attr($name);?>" value="1" <?php checked((bool)$checked);?>> <span><?php echo esc_html($label);?></span></label><?php }
	private function __construct() {}
}
